template <>
tagimg::ArtworkFilter
Argument<tagimg::ArtworkFilter>::convert(const response::Value &value) {
  const auto defaultValue = []() {
    response::Value values(response::Type::Map);
    response::Value entry;

    entry = response::Value(response::Type::EnumValue);
    entry.set<std::string>(R"gql(ALL)gql");
    values.emplace_back("includeMode", std::move(entry));
    entry = response::Value(false);
    values.emplace_back("expandIncludeTagDescendants", std::move(entry));
    entry = response::Value(false);
    values.emplace_back("expandExcludeTagDescendants", std::move(entry));

    return values;
  }();

  auto valueTitle = service::ModifiedArgument<std::string>::require<
      service::TypeModifier::Nullable>("title", value);
  auto valueEntityIds = service::ModifiedArgument<response::IdType>::require<
      service::TypeModifier::Nullable, service::TypeModifier::List>("entityIds",
                                                                    value);
  auto valueArtistIds = service::ModifiedArgument<response::IdType>::require<
      service::TypeModifier::Nullable, service::TypeModifier::List>("artistIds",
                                                                    value);
  auto valueIncludeTagIds =
      service::ModifiedArgument<response::IdType>::require<
          service::TypeModifier::Nullable, service::TypeModifier::List>(
          "includeTagIds", value);
  auto pairIncludeMode = service::ModifiedArgument<tagimg::TagMatchMode>::find<
      service::TypeModifier::Nullable>("includeMode", value);
  auto valueIncludeMode =
      (pairIncludeMode.second
           ? pairIncludeMode.first
           : service::ModifiedArgument<tagimg::TagMatchMode>::require<
                 service::TypeModifier::Nullable>("includeMode", defaultValue));
  auto pairExpandIncludeTagDescendants =
      service::ModifiedArgument<bool>::find<service::TypeModifier::Nullable>(
          "expandIncludeTagDescendants", value);
  auto valueExpandIncludeTagDescendants =
      (pairExpandIncludeTagDescendants.second
           ? std::move(pairExpandIncludeTagDescendants.first)
           : service::ModifiedArgument<bool>::require<
                 service::TypeModifier::Nullable>("expandIncludeTagDescendants",
                                                  defaultValue));
  auto valueExcludeTagIds =
      service::ModifiedArgument<response::IdType>::require<
          service::TypeModifier::Nullable, service::TypeModifier::List>(
          "excludeTagIds", value);
  auto pairExpandExcludeTagDescendants =
      service::ModifiedArgument<bool>::find<service::TypeModifier::Nullable>(
          "expandExcludeTagDescendants", value);
  auto valueExpandExcludeTagDescendants =
      (pairExpandExcludeTagDescendants.second
           ? std::move(pairExpandExcludeTagDescendants.first)
           : service::ModifiedArgument<bool>::require<
                 service::TypeModifier::Nullable>("expandExcludeTagDescendants",
                                                  defaultValue));

  return tagimg::ArtworkFilter{std::move(valueTitle),
                               std::move(valueEntityIds),
                               std::move(valueArtistIds),
                               std::move(valueIncludeTagIds),
                               valueIncludeMode,
                               std::move(valueExpandIncludeTagDescendants),
                               std::move(valueExcludeTagIds),
                               std::move(valueExpandExcludeTagDescendants)};
}

template <>
tagimg::AddArtworkInput
Argument<tagimg::AddArtworkInput>::convert(const response::Value &value) {
  auto valueEntityIds = service::ModifiedArgument<response::IdType>::require<
      service::TypeModifier::List>("entityIds", value);
  auto valueTitle =
      service::ModifiedArgument<std::string>::require("title", value);
  auto valueDescription = service::ModifiedArgument<std::string>::require<
      service::TypeModifier::Nullable>("description", value);
  auto valuePublishedAt = service::ModifiedArgument<std::string>::require<
      service::TypeModifier::Nullable>("publishedAt", value);
  auto valueTagIds = service::ModifiedArgument<response::IdType>::require<
      service::TypeModifier::Nullable, service::TypeModifier::List>("tagIds",
                                                                    value);
  auto valueArtistIds = service::ModifiedArgument<response::IdType>::require<
      service::TypeModifier::Nullable, service::TypeModifier::List>("artistIds",
                                                                    value);

  return tagimg::AddArtworkInput{
      std::move(valueEntityIds),   std::move(valueTitle),
      std::move(valueDescription), std::move(valuePublishedAt),
      std::move(valueTagIds),      std::move(valueArtistIds)};
}

