void AddTypesToSchema(const std::shared_ptr<schema::Schema> &schema) {
  auto typeTagMatchMode = schema::EnumType::Make(R"gql(TagMatchMode)gql"sv,
                                                 R"md(标签匹配方式。)md"sv);
  schema->AddType(R"gql(TagMatchMode)gql"sv, typeTagMatchMode);
  auto typeArtworkOrderField = schema::EnumType::Make(
      R"gql(ArtworkOrderField)gql"sv, R"md(作品排序字段。)md"sv);
  schema->AddType(R"gql(ArtworkOrderField)gql"sv, typeArtworkOrderField);
  auto typeSortDirection =
      schema::EnumType::Make(R"gql(SortDirection)gql"sv, R"md(排序方向。)md"sv);
  schema->AddType(R"gql(SortDirection)gql"sv, typeSortDirection);
  auto typeArtworkFilter = schema::InputObjectType::Make(
      R"gql(ArtworkFilter)gql"sv, R"md(作品过滤条件。)md"sv);
  schema->AddType(R"gql(ArtworkFilter)gql"sv, typeArtworkFilter);
  auto typeAddArtworkInput = schema::InputObjectType::Make(
      R"gql(AddArtworkInput)gql"sv,
      R"md(提交一次图片扫描任务所需的参数。)md"sv);
  schema->AddType(R"gql(AddArtworkInput)gql"sv, typeAddArtworkInput);
  auto typeQuery =
      schema::ObjectType::Make(R"gql(Query)gql"sv, R"md(根查询类型。)md"sv);
  schema->AddType(R"gql(Query)gql"sv, typeQuery);
  auto typeArtworkConnection = schema::ObjectType::Make(
      R"gql(ArtworkConnection)gql"sv, R"md(分页结果。)md"sv);
  schema->AddType(R"gql(ArtworkConnection)gql"sv, typeArtworkConnection);
  auto typeArtwork =
      schema::ObjectType::Make(R"gql(Artwork)gql"sv, R"md(已入库的作品。)md"sv);
  schema->AddType(R"gql(Artwork)gql"sv, typeArtwork);
  auto typeTag = schema::ObjectType::Make(R"gql(Tag)gql"sv, R"md(标签。)md"sv);
  schema->AddType(R"gql(Tag)gql"sv, typeTag);
  auto typeTagPath =
      schema::ObjectType::Make(R"gql(TagPath)gql"sv, R"md(标签路径。)md"sv);
  schema->AddType(R"gql(TagPath)gql"sv, typeTagPath);
  auto typeArtist =
      schema::ObjectType::Make(R"gql(Artist)gql"sv, R"md(艺术家。)md"sv);
  schema->AddType(R"gql(Artist)gql"sv, typeArtist);
  auto typeMutation =
      schema::ObjectType::Make(R"gql(Mutation)gql"sv, R"md(根变更类型。)md"sv);
  schema->AddType(R"gql(Mutation)gql"sv, typeMutation);

  typeTagMatchMode->AddEnumValues(
      {{service::s_namesTagMatchMode[static_cast<size_t>(
            tagimg::TagMatchMode::ALL)],
        R"md(每个请求的标签都至少命中一个。)md"sv, std::nullopt},
       {service::s_namesTagMatchMode[static_cast<size_t>(
            tagimg::TagMatchMode::ANY)],
        R"md(命中任意一个请求的标签即可。)md"sv, std::nullopt}});
  typeArtworkOrderField->AddEnumValues(
      {{service::s_namesArtworkOrderField[static_cast<size_t>(
            tagimg::ArtworkOrderField::CREATED_AT)],
        R"md()md"sv, std::nullopt},
       {service::s_namesArtworkOrderField[static_cast<size_t>(
            tagimg::ArtworkOrderField::PUBLISHED_AT)],
        R"md()md"sv, std::nullopt},
       {service::s_namesArtworkOrderField[static_cast<size_t>(
            tagimg::ArtworkOrderField::TITLE)],
        R"md()md"sv, std::nullopt}});
  typeSortDirection->AddEnumValues(
      {{service::s_namesSortDirection[static_cast<size_t>(
            tagimg::SortDirection::ASC)],
        R"md()md"sv, std::nullopt},
       {service::s_namesSortDirection[static_cast<size_t>(
            tagimg::SortDirection::DESC)],
        R"md()md"sv, std::nullopt}});

  typeArtworkFilter->AddInputValues(
      {schema::InputValue::Make(
           R"gql(title)gql"sv,
           R"md(标题子串匹配，区分大小写按数据库默认排序规则，最多 500 个字符。)md"sv,
           schema->LookupType(R"gql(String)gql"sv), R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(entityIds)gql"sv, R"md(作品包含其中任一实体即命中。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(artistIds)gql"sv, R"md(作品包含其中任一艺术家即命中。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(includeTagIds)gql"sv, R"md(要求命中的标签 ID 集合。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(includeMode)gql"sv,
           R"md(includeTagIds 的匹配方式，默认全部命中。)md"sv,
           schema->LookupType(R"gql(TagMatchMode)gql"sv), R"gql(ALL)gql"sv),
       schema::InputValue::Make(R"gql(expandIncludeTagDescendants)gql"sv,
                                R"md(includeTagIds 是否递归包含后代标签。)md"sv,
                                schema->LookupType(R"gql(Boolean)gql"sv),
                                R"gql(false)gql"sv),
       schema::InputValue::Make(
           R"gql(excludeTagIds)gql"sv,
           R"md(要求排除的标签 ID 集合，作品不能命中其中任何一个。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv),
       schema::InputValue::Make(R"gql(expandExcludeTagDescendants)gql"sv,
                                R"md(excludeTagIds 是否递归包含后代标签。)md"sv,
                                schema->LookupType(R"gql(Boolean)gql"sv),
                                R"gql(false)gql"sv)});
  typeAddArtworkInput->AddInputValues(
      {schema::InputValue::Make(
           R"gql(entityIds)gql"sv,
           R"md(图片实体 ID，1 到 20 个，不能重复。)md"sv,
           schema->WrapType(
               introspection::TypeKind::NON_NULL,
               schema->WrapType(
                   introspection::TypeKind::LIST,
                   schema->WrapType(introspection::TypeKind::NON_NULL,
                                    schema->LookupType(R"gql(ID)gql"sv)))),
           R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(title)gql"sv, R"md(作品标题，1 到 500 个字符。)md"sv,
           schema->WrapType(introspection::TypeKind::NON_NULL,
                            schema->LookupType(R"gql(String)gql"sv)),
           R"gql()gql"sv),
       schema::InputValue::Make(R"gql(description)gql"sv,
                                R"md(作品描述，缺省或 null 时写入 NULL。)md"sv,
                                schema->LookupType(R"gql(String)gql"sv),
                                R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(publishedAt)gql"sv,
           R"md(RFC3339 格式的原始发布时间，缺省或 null 时写入 NULL。)md"sv,
           schema->LookupType(R"gql(String)gql"sv), R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(tagIds)gql"sv, R"md(已存在的标签 ID，直接挂到作品上。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv),
       schema::InputValue::Make(
           R"gql(artistIds)gql"sv,
           R"md(已存在的艺术家 ID，写入 artwork_artists。)md"sv,
           schema->WrapType(
               introspection::TypeKind::LIST,
               schema->WrapType(introspection::TypeKind::NON_NULL,
                                schema->LookupType(R"gql(ID)gql"sv))),
           R"gql()gql"sv)});

  AddQueryDetails(typeQuery, schema);
  AddArtworkConnectionDetails(typeArtworkConnection, schema);
  AddArtworkDetails(typeArtwork, schema);
  AddTagDetails(typeTag, schema);
  AddTagPathDetails(typeTagPath, schema);
  AddArtistDetails(typeArtist, schema);
  AddMutationDetails(typeMutation, schema);

  schema->AddQueryType(typeQuery);
  schema->AddMutationType(typeMutation);
}

std::shared_ptr<schema::Schema> GetSchema() {
  static std::weak_ptr<schema::Schema> s_wpSchema;
  auto schema = s_wpSchema.lock();

  if (!schema) {
    schema = std::make_shared<schema::Schema>(false, R"md()md"sv);
    introspection::AddTypesToSchema(schema);
    AddTypesToSchema(schema);
    s_wpSchema = schema;
  }

  return schema;
}

